code.source:
#include <iostream>
using namespace std;

int main() {
    auto square = [](int x) {
        return x * x;
    };
    cout << square(6) << endl;
    cout << square(9) << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int offset = 100;
    auto shift = [offset](int x) {
        return x + offset;
    };
    cout << shift(5) << endl;
    return 0;
}

